import{_ as t,c as i,o as h,ae as a}from"./chunks/framework.BGWP4WZ_.js";const p=JSON.parse('{"title":"Tích hợp Home Assistant MCP","description":"","frontmatter":{},"headers":[],"relativePath":"vi/mcp/ha.md","filePath":"vi/mcp/ha.md"}'),o={name:"vi/mcp/ha.md"};function c(l,n,e,s,r,u){return h(),i("div",null,n[0]||(n[0]=[a(`<h1 id="tich-hop-home-assistant-mcp" tabindex="-1">Tích hợp Home Assistant MCP <a class="header-anchor" href="#tich-hop-home-assistant-mcp" aria-label="Permalink to &quot;Tích hợp Home Assistant MCP&quot;">​</a></h1><p>Nhằm nâng cao tính linh hoạt và ổn định về kiến trúc, py-xiaozhi đã loại bỏ tích hợp Home Assistant (HA) gắn sẵn. Hiện tại, bạn có thể kết nối HA thông qua plugin mở rộng Home Assistant MCP dựa trên WSS, kết nối trực tiếp tới máy chủ XiaoZhi AI bằng giao thức MCP mà không cần bất kỳ máy chủ trung gian nào. Plugin này được c1pher-cn duy trì mã nguồn mở, hỗ trợ đầy đủ truy vấn trạng thái thiết bị, điều khiển thực thể (entity) và quản lý tự động hóa.</p><p>Địa chỉ dự án: <a href="https://github.com/c1pher-cn/ha-mcp-for-xiaozhi" target="_blank" rel="noreferrer">ha-mcp-for-xiaozhi</a></p><h2 id="tinh-nang-cua-plugin" tabindex="-1">Tính năng của plugin <a class="header-anchor" href="#tinh-nang-cua-plugin" aria-label="Permalink to &quot;Tính năng của plugin&quot;">​</a></h2><h3 id="nang-luc-cot-loi" tabindex="-1">Năng lực cốt lõi <a class="header-anchor" href="#nang-luc-cot-loi" aria-label="Permalink to &quot;Năng lực cốt lõi&quot;">​</a></h3><ol><li><strong>Kết nối trực tiếp máy chủ XiaoZhi</strong>: Home Assistant đóng vai trò MCP server, kết nối trực tiếp tới máy chủ XiaoZhi qua giao thức WebSocket mà không cần trung chuyển</li><li><strong>Ủy quyền nhiều nhóm API</strong>: Chọn đồng thời nhiều nhóm API trên cùng một thực thể (API điều khiển tích hợp của Home Assistant, MCP Server do người dùng tự định nghĩa)</li><li><strong>Hỗ trợ nhiều thực thể</strong>: Hỗ trợ cấu hình đồng thời nhiều phiên bản thực thể</li><li><strong>Tích hợp HACS</strong>: Cài đặt một chạm qua kho HACS, dễ dàng quản lý và cập nhật</li></ol><h3 id="uu-điem-ky-thuat" tabindex="-1">Ưu điểm kỹ thuật <a class="header-anchor" href="#uu-điem-ky-thuat" aria-label="Permalink to &quot;Ưu điểm kỹ thuật&quot;">​</a></h3><ul><li><strong>Độ trễ thấp</strong>: Kiến trúc kết nối trực tiếp giúp giảm độ trễ truyền qua trung gian</li><li><strong>Độ tin cậy cao</strong>: Dựa trên kết nối WebSocket duy trì dài hạn, ổn định hơn</li><li><strong>Dễ mở rộng</strong>: Hỗ trợ proxy cho các MCP Server khác, khả năng mở rộng mạnh mẽ</li><li><strong>Dễ bảo trì</strong>: Quản lý qua HACS và tự động cập nhật</li></ul><h2 id="cac-tinh-huong-su-dung-pho-bien" tabindex="-1">Các tình huống sử dụng phổ biến <a class="header-anchor" href="#cac-tinh-huong-su-dung-pho-bien" aria-label="Permalink to &quot;Các tình huống sử dụng phổ biến&quot;">​</a></h2><p><strong>Truy vấn trạng thái thiết bị:</strong></p><ul><li>&quot;Đèn phòng khách hiện đang ở trạng thái nào&quot;</li><li>&quot;Xem trạng thái tất cả các đèn&quot;</li><li>&quot;Cảm biến nhiệt độ đang báo bao nhiêu độ&quot;</li><li>&quot;Điều hòa hiện có đang bật không&quot;</li></ul><p><strong>Điều khiển thiết bị:</strong></p><ul><li>&quot;Bật đèn phòng khách&quot;</li><li>&quot;Tắt tất cả đèn&quot;</li><li>&quot;Đặt nhiệt độ điều hòa lên 25 độ&quot;</li><li>&quot;Chỉnh độ sáng đèn phòng khách lên 80%&quot;</li></ul><p><strong>Điều khiển ngữ cảnh (Scene):</strong></p><ul><li>&quot;Bật chế độ ngủ&quot;</li><li>&quot;Kích hoạt ngữ cảnh về nhà&quot;</li><li>&quot;Chạy ngữ cảnh chúc ngủ ngon&quot;</li><li>&quot;Bật chế độ tiệc tùng&quot;</li></ul><p><strong>Điều khiển nâng cao:</strong></p><ul><li>&quot;Điều khiển TV thông qua script&quot;</li><li>&quot;Chạy tự động hóa tùy chỉnh&quot;</li><li>&quot;Điều khiển thiết bị đa phương tiện&quot;</li><li>&quot;Quản lý hệ thống an ninh&quot;</li></ul><h2 id="huong-dan-cai-đat" tabindex="-1">Hướng dẫn cài đặt <a class="header-anchor" href="#huong-dan-cai-đat" aria-label="Permalink to &quot;Hướng dẫn cài đặt&quot;">​</a></h2><h3 id="yeu-cau-truoc-khi-cai-đat" tabindex="-1">Yêu cầu trước khi cài đặt <a class="header-anchor" href="#yeu-cau-truoc-khi-cai-đat" aria-label="Permalink to &quot;Yêu cầu trước khi cài đặt&quot;">​</a></h3><ul><li>Home Assistant đã được cài đặt và đang chạy</li><li>Đã cài đặt HACS (Home Assistant Community Store)</li><li>Có tài khoản XiaoZhi AI và địa chỉ điểm truy cập MCP (MCP endpoint)</li></ul><h3 id="cac-buoc-cai-đat" tabindex="-1">Các bước cài đặt <a class="header-anchor" href="#cac-buoc-cai-đat" aria-label="Permalink to &quot;Các bước cài đặt&quot;">​</a></h3><h4 id="_1-cai-đat-qua-hacs" tabindex="-1">1. Cài đặt qua HACS <a class="header-anchor" href="#_1-cai-đat-qua-hacs" aria-label="Permalink to &quot;1. Cài đặt qua HACS&quot;">​</a></h4><ol><li>Mở HACS, tìm kiếm <code>xiaozhi</code> hoặc <code>ha-mcp-for-xiaozhi</code></li></ol><img width="700" alt="Giao diện tìm kiếm HACS" src="https://github.com/user-attachments/assets/fa49ee7c-b503-49fa-ad63-512499fa3885"><ol start="2"><li>Nhấp tải xuống và cài đặt plugin</li></ol><img width="500" alt="Giao diện tải xuống plugin" src="https://github.com/user-attachments/assets/1ee75d6f-e1b0-4073-a2c7-ee0d72d002ca"><ol start="3"><li>Khởi động lại Home Assistant</li></ol><h4 id="_2-cai-đat-thu-cong" tabindex="-1">2. Cài đặt thủ công <a class="header-anchor" href="#_2-cai-đat-thu-cong" aria-label="Permalink to &quot;2. Cài đặt thủ công&quot;">​</a></h4><p>Nếu không thể cài đặt qua HACS, bạn có thể tải thủ công:</p><ol><li>Tải phiên bản mới nhất từ <a href="https://github.com/c1pher-cn/ha-mcp-for-xiaozhi/releases" target="_blank" rel="noreferrer">GitHub Releases</a></li><li>Giải nén vào thư mục <code>custom_components</code></li><li>Khởi động lại Home Assistant</li></ol><h3 id="cac-buoc-cau-hinh" tabindex="-1">Các bước cấu hình <a class="header-anchor" href="#cac-buoc-cau-hinh" aria-label="Permalink to &quot;Các bước cấu hình&quot;">​</a></h3><h4 id="_1-them-tich-hop" tabindex="-1">1. Thêm tích hợp <a class="header-anchor" href="#_1-them-tich-hop" aria-label="Permalink to &quot;1. Thêm tích hợp&quot;">​</a></h4><ol><li>Vào <strong>Cài đặt &gt; Thiết bị &amp; Dịch vụ &gt; Thêm tích hợp</strong> (<strong>Settings &gt; Devices &amp; Services &gt; Add Integration</strong>)</li><li>Tìm kiếm &quot;Mcp&quot; hoặc &quot;MCP Server for Xiaozhi&quot;</li></ol><img width="600" alt="Giao diện thêm tích hợp" src="https://github.com/user-attachments/assets/07a70fe1-8c6e-4679-84df-1ea05114b271"><ol start="3"><li>Chọn và nhấp thêm</li></ol><h4 id="_2-cau-hinh-tham-so" tabindex="-1">2. Cấu hình tham số <a class="header-anchor" href="#_2-cau-hinh-tham-so" aria-label="Permalink to &quot;2. Cấu hình tham số&quot;">​</a></h4><p>Giao diện cấu hình yêu cầu điền các thông tin sau:</p><p><strong>Cấu hình cơ bản:</strong></p><ul><li><strong>Địa chỉ điểm truy cập XiaoZhi MCP</strong>: Địa chỉ MCP lấy từ trang quản trị XiaoZhi AI</li><li><strong>Tên thiết bị</strong>: Đặt tên nhận diện cho phiên bản Home Assistant này</li></ul><p><strong>Chọn nhóm API:</strong></p><ul><li><strong>Assist</strong>: Tính năng điều khiển tích hợp sẵn của Home Assistant</li><li><strong>MCP Server khác</strong>: Nếu bạn đã cấu hình các máy chủ MCP khác trong Home Assistant, có thể chọn để ủy quyền chung cho XiaoZhi</li></ul><img width="600" alt="Giao diện cấu hình" src="https://github.com/user-attachments/assets/38e98fde-8a6c-4434-932c-840c25dc6e28"><h4 id="_3-cau-hinh-cong-khai-thuc-the-expose" tabindex="-1">3. Cấu hình công khai thực thể (Expose) <a class="header-anchor" href="#_3-cau-hinh-cong-khai-thuc-the-expose" aria-label="Permalink to &quot;3. Cấu hình công khai thực thể (Expose)&quot;">​</a></h4><p>Để XiaoZhi có thể điều khiển thiết bị, cần công khai các thực thể tương ứng:</p><ol><li>Vào <strong>Cài đặt &gt; Trợ lý giọng nói &gt; Công khai</strong> (<strong>Settings &gt; Voice assistants &gt; Expose</strong>)</li><li>Chọn các thiết bị và thực thể cần cho phép XiaoZhi điều khiển</li><li>Lưu cài đặt</li></ol><h4 id="_4-xac-minh-ket-noi" tabindex="-1">4. Xác minh kết nối <a class="header-anchor" href="#_4-xac-minh-ket-noi" aria-label="Permalink to &quot;4. Xác minh kết nối&quot;">​</a></h4><ol><li>Sau khi hoàn tất cấu hình, chờ khoảng 1 phút</li><li>Đăng nhập vào trang quản trị XiaoZhi AI, mở trang điểm truy cập MCP</li><li>Nhấp làm mới và kiểm tra xem trạng thái kết nối đã bình thường chưa</li></ol><img width="600" alt="Kiểm tra trạng thái kết nối" src="https://github.com/user-attachments/assets/ace79a44-6197-4e94-8c49-ab9048ed4502"><h2 id="vi-du-su-dung" tabindex="-1">Ví dụ sử dụng <a class="header-anchor" href="#vi-du-su-dung" aria-label="Permalink to &quot;Ví dụ sử dụng&quot;">​</a></h2><h3 id="đieu-khien-thiet-bi-co-ban" tabindex="-1">Điều khiển thiết bị cơ bản <a class="header-anchor" href="#đieu-khien-thiet-bi-co-ban" aria-label="Permalink to &quot;Điều khiển thiết bị cơ bản&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Người dùng: &quot;Bật đèn phòng khách&quot;</span></span>
<span class="line"><span>XiaoZhi: &quot;Vâng, tôi đã bật đèn phòng khách cho bạn&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Người dùng: &quot;Chỉnh nhiệt độ điều hòa lên 26 độ&quot;</span></span>
<span class="line"><span>XiaoZhi: &quot;Đã đặt nhiệt độ điều hòa thành 26 độ&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Người dùng: &quot;Tắt tất cả đèn&quot;</span></span>
<span class="line"><span>XiaoZhi: &quot;Tôi đã tắt toàn bộ đèn cho bạn&quot;</span></span></code></pre></div><h3 id="truy-van-trang-thai" tabindex="-1">Truy vấn trạng thái <a class="header-anchor" href="#truy-van-trang-thai" aria-label="Permalink to &quot;Truy vấn trạng thái&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Người dùng: &quot;Nhiệt độ phòng khách hiện tại là bao nhiêu&quot;</span></span>
<span class="line"><span>XiaoZhi: &quot;Cảm biến nhiệt độ phòng khách báo nhiệt độ hiện tại là 23.5 độ&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Người dùng: &quot;Những đèn nào hiện đang bật&quot;</span></span>
<span class="line"><span>XiaoZhi: &quot;Các đèn đang bật hiện tại gồm: đèn phòng khách, đèn ngủ đầu giường&quot;</span></span></code></pre></div><h3 id="đieu-khien-ngu-canh" tabindex="-1">Điều khiển ngữ cảnh <a class="header-anchor" href="#đieu-khien-ngu-canh" aria-label="Permalink to &quot;Điều khiển ngữ cảnh&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Người dùng: &quot;Chạy chế độ ngủ&quot;</span></span>
<span class="line"><span>XiaoZhi: &quot;Đã kích hoạt ngữ cảnh chế độ ngủ cho bạn, toàn bộ đèn đã tắt và rèm cửa đã kéo lại&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Người dùng: &quot;Bật ngữ cảnh về nhà&quot;</span></span>
<span class="line"><span>XiaoZhi: &quot;Chào mừng về nhà! Đã bật đèn phòng khách và đèn sảnh, điều hòa đã được chỉnh về mức nhiệt thoải mái&quot;</span></span></code></pre></div><h2 id="huong-dan-go-loi" tabindex="-1">Hướng dẫn gỡ lỗi <a class="header-anchor" href="#huong-dan-go-loi" aria-label="Permalink to &quot;Hướng dẫn gỡ lỗi&quot;">​</a></h2><h3 id="_1-kiem-tra-thuc-the-đa-cong-khai" tabindex="-1">1. Kiểm tra thực thể đã công khai <a class="header-anchor" href="#_1-kiem-tra-thuc-the-đa-cong-khai" aria-label="Permalink to &quot;1. Kiểm tra thực thể đã công khai&quot;">​</a></h3><p>Số lượng công cụ được hiển thị phụ thuộc vào loại thực thể bạn đã công khai cho trợ lý giọng nói Home Assistant:</p><ul><li>Vào <strong>Cài đặt &gt; Trợ lý giọng nói &gt; Công khai</strong> (<strong>Settings &gt; Voice assistants &gt; Expose</strong>)</li><li>Đảm bảo các thiết bị cần điều khiển đã được thêm vào danh sách công khai</li></ul><h3 id="_2-yeu-cau-phien-ban" tabindex="-1">2. Yêu cầu phiên bản <a class="header-anchor" href="#_2-yeu-cau-phien-ban" aria-label="Permalink to &quot;2. Yêu cầu phiên bản&quot;">​</a></h3><p>Khuyến nghị sử dụng phiên bản Home Assistant mới nhất:</p><ul><li>Các phiên bản mới cung cấp bộ công cụ và API đầy đủ hơn</li><li>Phiên bản tháng 5 có cải tiến rõ rệt về hỗ trợ công cụ so với phiên bản tháng 3</li></ul><h3 id="_3-phuong-phap-go-loi" tabindex="-1">3. Phương pháp gỡ lỗi <a class="header-anchor" href="#_3-phuong-phap-go-loi" aria-label="Permalink to &quot;3. Phương pháp gỡ lỗi&quot;">​</a></h3><p>Khi kết quả điều khiển không như mong đợi:</p><p><strong>Xem lịch sử trò chuyện XiaoZhi:</strong></p><ol><li>Kiểm tra xem XiaoZhi hiểu và xử lý câu lệnh như thế nào</li><li>Xác nhận xem công cụ Home Assistant có được gọi không</li><li>Phân tích xem tham số truyền vào có chính xác không</li></ol><p><strong>Vấn đề đã biết:</strong></p><ul><li>Điều khiển đèn có thể xung đột với điều khiển màn hình tích hợp sẵn</li></ul><h3 id="_4-nhat-ky-go-loi-debug-logs" tabindex="-1">4. Nhật ký gỡ lỗi (Debug logs) <a class="header-anchor" href="#_4-nhat-ky-go-loi-debug-logs" aria-label="Permalink to &quot;4. Nhật ký gỡ lỗi (Debug logs)&quot;">​</a></h3><p>Nếu lời gọi function của Home Assistant chính xác nhưng thực thi bất thường:</p><ol><li>Bật nhật ký gỡ lỗi (debug logging) cho plugin này trong Home Assistant</li><li>Tái hiện lại thao tác gây lỗi</li><li>Xem chi tiết quá trình thực thi trong nhật ký</li></ol><h2 id="video-minh-hoa" tabindex="-1">Video minh họa <a class="header-anchor" href="#video-minh-hoa" aria-label="Permalink to &quot;Video minh họa&quot;">​</a></h2><p>Để hiểu rõ hơn các tính năng của plugin, bạn có thể xem các video minh họa sau:</p><ul><li><a href="https://www.bilibili.com/video/BV1XdjJzeEwe" target="_blank" rel="noreferrer">Video hướng dẫn tích hợp</a> - Quy trình cài đặt và cấu hình cơ bản</li><li><a href="https://www.bilibili.com/video/BV18DM8zuEYV" target="_blank" rel="noreferrer">Minh họa điều khiển TV</a> - Điều khiển TV thông qua script tùy chỉnh</li><li><a href="https://www.bilibili.com/video/BV1SruXzqEW5" target="_blank" rel="noreferrer">Hướng dẫn nâng cao</a> - Hướng dẫn chi tiết về Home Assistant, LLM, MCP và XiaoZhi</li></ul><h2 id="khac-phuc-su-co" tabindex="-1">Khắc phục sự cố <a class="header-anchor" href="#khac-phuc-su-co" aria-label="Permalink to &quot;Khắc phục sự cố&quot;">​</a></h2><h3 id="cac-van-đe-thuong-gap" tabindex="-1">Các vấn đề thường gặp <a class="header-anchor" href="#cac-van-đe-thuong-gap" aria-label="Permalink to &quot;Các vấn đề thường gặp&quot;">​</a></h3><p><strong>1. Kết nối thất bại</strong></p><ul><li>Kiểm tra xem địa chỉ điểm truy cập XiaoZhi MCP có chính xác không</li><li>Xác nhận kết nối mạng của Home Assistant hoạt động bình thường</li><li>Kiểm tra cấu hình tường lửa</li></ul><p><strong>2. Không thể điều khiển thiết bị</strong></p><ul><li>Xác nhận thiết bị đã được công khai trong trợ lý giọng nói</li><li>Kiểm tra trạng thái thực thể của thiết bị có bình thường không</li><li>Xác minh xem thiết bị có hỗ trợ thao tác tương ứng hay không</li></ul><p><strong>3. Xung đột một số tính năng</strong></p><ul><li>Tạm thời tắt tính năng tích hợp sẵn</li><li>Điều chỉnh tên thiết bị để tránh trùng lặp</li><li>Chờ bản cập nhật tính năng chọn công cụ của máy chủ XiaoZhi</li></ul><p><strong>4. Phản hồi chậm</strong></p><ul><li>Kiểm tra chất lượng kết nối mạng</li><li>Tối ưu hiệu năng Home Assistant</li><li>Giảm bớt các thực thể công khai không cần thiết</li></ul><h3 id="meo-go-loi" tabindex="-1">Mẹo gỡ lỗi <a class="header-anchor" href="#meo-go-loi" aria-label="Permalink to &quot;Mẹo gỡ lỗi&quot;">​</a></h3><ol><li>Bật ghi log chi tiết</li><li>Kiểm tra lần lượt các chức năng cơ bản</li><li>So sánh với cấu hình thiết bị đang hoạt động bình thường</li><li>Tham khảo thảo luận và issues từ cộng đồng</li></ol><h2 id="ho-tro-cong-đong" tabindex="-1">Hỗ trợ cộng đồng <a class="header-anchor" href="#ho-tro-cong-đong" aria-label="Permalink to &quot;Hỗ trợ cộng đồng&quot;">​</a></h2><h3 id="lien-ket-du-an" tabindex="-1">Liên kết dự án <a class="header-anchor" href="#lien-ket-du-an" aria-label="Permalink to &quot;Liên kết dự án&quot;">​</a></h3><ul><li><strong>Kho GitHub</strong>: <a href="https://github.com/c1pher-cn/ha-mcp-for-xiaozhi" target="_blank" rel="noreferrer">ha-mcp-for-xiaozhi</a></li><li><strong>Báo lỗi</strong>: <a href="https://github.com/c1pher-cn/ha-mcp-for-xiaozhi/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li><li><strong>Đề xuất tính năng</strong>: <a href="https://github.com/c1pher-cn/ha-mcp-for-xiaozhi/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a></li></ul>`,89)]))}const m=t(o,[["render",c]]);export{p as __pageData,m as default};
